insert into public.lessons (id, level, position, published, data) values
  ('fba-basics', 0, 0, true, '{"minutes":5,"icon":"globe","title":{"uz":"Amazon FBA qanday ishlaydi","ru":"Как работает Amazon FBA"},"summary":{"uz":"Tovar zavoddan xaridorgacha qanday yo''l bosadi.","ru":"Путь товара от фабрики до покупателя."},"slides":[{"kind":"learn","title":{"uz":"FBA nima?","ru":"Что такое FBA?"},"body":{"uz":"FBA (Fulfillment by Amazon) – siz tovarni Amazon omboriga yuborasiz. Amazon uni saqlaydi, xaridorga yetkazadi va qaytarishlarni boshqaradi.","ru":"FBA (Fulfillment by Amazon): вы отправляете товар на склад Amazon. Amazon хранит его, доставляет покупателю и занимается возвратами."},"visual":{"kind":"flow","steps":[{"uz":"Zavod","ru":"Фабрика"},{"uz":"Amazon ombori","ru":"Склад Amazon"},{"uz":"Xaridor","ru":"Покупатель"}]}},{"kind":"learn","title":{"uz":"Pul qanday aylanadi","ru":"Как движутся деньги"},"body":{"uz":"Xaridor to''laydi. Amazon o''z komissiyasi va xizmat to''lovlarini ushlab qoladi, qolgani sizga o''tadi. Tovar va yetkazish narxini ham hisobga olsangiz, foyda chiqadi.","ru":"Покупатель платит. Amazon удерживает комиссию и плату за услуги, остальное переводит вам. Если вычесть стоимость товара и доставки, получится прибыль."},"visual":{"kind":"formula","lines":[{"label":{"uz":"Sotuv narxi","ru":"Цена продажи"}},{"op":"−","label":{"uz":"Amazon komissiyasi","ru":"Комиссия Amazon"}},{"op":"−","label":{"uz":"FBA to''lovi","ru":"Плата FBA"}},{"op":"−","label":{"uz":"Tovar va yetkazish","ru":"Товар и доставка"}},{"op":"=","label":{"uz":"Sizning foydangiz","ru":"Ваша прибыль"}}]}},{"kind":"learn","title":{"uz":"Kim nima qiladi","ru":"Кто что делает"},"body":{"uz":"FBA ko''p ishni o''z zimmasiga oladi, lekin mahsulot va uning sifati uchun javobgar sizsiz.","ru":"FBA берёт на себя много работы, но за товар и его качество отвечаете вы."},"visual":{"kind":"compare","left":{"title":{"uz":"Siz","ru":"Вы"},"items":[{"uz":"Mahsulot tanlash","ru":"Выбор товара"},{"uz":"Yetkazib beruvchi","ru":"Поставщик"},{"uz":"Sifat","ru":"Качество"},{"uz":"Listing va reklama","ru":"Карточка и реклама"}]},"right":{"title":{"uz":"Amazon","ru":"Amazon"},"items":[{"uz":"Saqlash","ru":"Хранение"},{"uz":"Qadoqlash va jo''natish","ru":"Упаковка и отправка"},{"uz":"Mijozlarga xizmat","ru":"Поддержка клиентов"},{"uz":"Qaytarishlar","ru":"Возвраты"}]}}},{"kind":"quiz","question":{"uz":"FBA''da xaridorga tovarni kim yetkazadi?","ru":"Кто доставляет товар покупателю при FBA?"},"options":[{"uz":"Siz o''zingiz","ru":"Вы сами"},{"uz":"Amazon","ru":"Amazon"},{"uz":"Zavod","ru":"Фабрика"}],"correct":1,"explain":{"uz":"Tovar Amazon omborida turadi va Amazon uni o''zi yetkazadi.","ru":"Товар лежит на складе Amazon, и Amazon сам его доставляет."}}]}'::jsonb),
  ('account-age', 0, 1, true, '{"minutes":4,"icon":"shield","title":{"uz":"Hisob va yosh qoidasi","ru":"Аккаунт и возраст"},"summary":{"uz":"Nega hisob ota-ona nomida bo''ladi.","ru":"Почему аккаунт оформляется на родителя."},"slides":[{"kind":"learn","title":{"uz":"Hisob kimga tegishli","ru":"На кого оформляется аккаунт"},"body":{"uz":"Amazon''da sotuvchi bo''lish uchun voyaga yetgan bo''lish kerak. Siz 18 yoshga to''lmaganingiz uchun hisob, to''lovlar va shartnomalar ota-onangiz yoki vasiyingiz nomida bo''ladi.","ru":"Продавцом на Amazon может быть только совершеннолетний. Пока вам нет 18, аккаунт, платежи и договоры оформляются на родителя или опекуна."},"visual":{"kind":"big","icon":"user","text":{"uz":"Hisob egasi: ota-ona yoki vasiy","ru":"Владелец аккаунта: родитель или опекун"}}},{"kind":"learn","title":{"uz":"Ro''yxatdan o''tish uchun nima kerak","ru":"Что нужно для регистрации"},"body":{"uz":"Amazon odatda quyidagilarni so''raydi. Aniq ro''yxatni ro''yxatdan o''tish sahifasida tekshiring.","ru":"Обычно Amazon запрашивает следующее. Точный список проверьте на странице регистрации."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Shaxsni tasdiqlovchi hujjat (pasport)","ru":"Документ, удостоверяющий личность (паспорт)"},{"uz":"Xalqaro to''lovga yaroqli bank kartasi","ru":"Банковская карта для международных платежей"},{"uz":"Pul qabul qilinadigan bank hisobi","ru":"Банковский счёт для выплат"},{"uz":"Telefon raqami va email","ru":"Телефон и email"},{"uz":"Soliq ma''lumotlari","ru":"Налоговые данные"}]}},{"kind":"learn","title":{"uz":"Uzum Market","ru":"Uzum Market"},"body":{"uz":"Uzum Market''da sotish uchun rasmiy ro''yxatdan o''tgan sotuvchi kerak, masalan yakka tartibdagi tadbirkor yoki kompaniya. Aniq talablarni Uzum''ning rasmiy sotuvchilar sahifasidan tekshiring.","ru":"Для продаж на Uzum Market нужен официально зарегистрированный продавец, например ИП или компания. Точные требования проверьте на официальной странице Uzum для продавцов."}},{"kind":"learn","title":{"uz":"Idrok sizni qanday himoya qiladi","ru":"Как Idrok вас защищает"},"body":{"uz":"Idrok faqat tadqiqot qiladi va tavsiya beradi. U pul sarflamaydi. Har bir xarid siz va ota-onangiz tomonidan tasdiqlanadi va jurnalga yoziladi.","ru":"Idrok только исследует и советует. Он не тратит деньги. Каждую покупку одобряете вы и ваши родители, и всё записывается в журнал."},"visual":{"kind":"flow","steps":[{"uz":"AI tavsiya","ru":"Совет ИИ"},{"uz":"Siz ko''rasiz","ru":"Вы проверяете"},{"uz":"Ota-ona tasdiqlaydi","ru":"Родитель одобряет"}]}},{"kind":"quiz","question":{"uz":"18 yoshga to''lmagan bo''lsangiz, Amazon hisobi kim nomida ochiladi?","ru":"На кого оформляется аккаунт Amazon, если вам нет 18?"},"options":[{"uz":"O''zim, yoshimni kattaroq yozib","ru":"На себя, указав больший возраст"},{"uz":"Ota-onam yoki vasiyim","ru":"На родителя или опекуна"},{"uz":"Do''stim","ru":"На друга"}],"correct":1,"explain":{"uz":"Yoshni noto''g''ri ko''rsatish qoidabuzarlik: hisob bloklanishi va pul muzlatilishi mumkin.","ru":"Указывать неверный возраст нельзя: аккаунт заблокируют, а деньги могут заморозить."}}]}'::jsonb),
  ('first-product', 0, 2, true, '{"minutes":5,"icon":"box","title":{"uz":"Xavfsiz birinchi mahsulot","ru":"Безопасный первый товар"},"summary":{"uz":"Qanday mahsulot boshlash uchun mos.","ru":"Какой товар подходит для старта."},"slides":[{"kind":"learn","title":{"uz":"Oddiydan boshlang","ru":"Начните с простого"},"body":{"uz":"Birinchi mahsulot xato qilsangiz ham kam zarar keltiradigan bo''lsin.","ru":"Первый товар должен быть таким, чтобы ошибка стоила недорого."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Kichik: oddiy qutiga sig''adi","ru":"Маленький: помещается в обычную коробку"},{"uz":"Yengil: 0,5 kg dan kam","ru":"Лёгкий: меньше 0,5 кг"},{"uz":"Sinmaydi","ru":"Не бьётся"},{"uz":"Arzon: dona narxi 5 $ gacha","ru":"Недорогой: до 5 $ за штуку"},{"uz":"Elektronikasiz","ru":"Без электроники"}]}},{"kind":"learn","title":{"uz":"Nimadan qochish kerak","ru":"Чего избегать"},"body":{"uz":"Bu toifalar uchun maxsus ruxsat, sertifikat yoki sinovlar kerak bo''ladi. Xato qilsangiz, tovar bloklanadi.","ru":"Для этих категорий нужны специальные разрешения, сертификаты или испытания. Ошибка = блокировка товара."},"visual":{"kind":"checklist","tone":"bad","items":[{"uz":"Batareyali va elektron tovarlar","ru":"Товары с батарейками и электроника"},{"uz":"Oziq-ovqat va ichimliklar","ru":"Еда и напитки"},{"uz":"Kosmetika va qo''shimchalar","ru":"Косметика и БАДы"},{"uz":"\"Davolaydi\" kabi tibbiy da''volar","ru":"Медицинские заявления вроде «лечит»"},{"uz":"Mashhur brend yoki personaj tasviri","ru":"Чужие бренды и персонажи"}]}},{"kind":"learn","title":{"uz":"Idrok cheklovlari","ru":"Ограничения Idrok"},"body":{"uz":"Mahsulotlar bo''limidagi 0-daraja cheklovlari aynan shu qoidalarni tekshiradi. Mahsulot ularga mos kelmasa, ogohlantirish chiqadi.","ru":"Ограничения уровня 0 в разделе «Товары» проверяют именно эти правила. Если товар не подходит, появится предупреждение."},"visual":{"kind":"big","icon":"shield","text":{"uz":"Cheklovlar sizni himoya qiladi","ru":"Ограничения вас защищают"}}},{"kind":"quiz","question":{"uz":"Qaysi biri birinchi mahsulot uchun eng mos?","ru":"Что лучше всего подходит как первый товар?"},"options":[{"uz":"Bluetooth quloqchin","ru":"Bluetooth-наушники"},{"uz":"Silikon oshxona qoshig''i","ru":"Силиконовая кухонная ложка"},{"uz":"Vitamin kapsulalari","ru":"Капсулы с витаминами"}],"correct":1,"explain":{"uz":"Qoshiq kichik, yengil, sinmaydi va elektronikasiz. Quloqchinda batareya bor, vitaminlar esa qo''shimcha.","ru":"Ложка маленькая, лёгкая, не бьётся и без электроники. В наушниках батарея, а витамины – это БАДы."}}]}'::jsonb),
  ('demand', 0, 3, true, '{"minutes":5,"icon":"chart","title":{"uz":"Talabni tekshirish","ru":"Проверка спроса"},"summary":{"uz":"Odamlar bu mahsulotni sotib olyaptimi?","ru":"Покупают ли люди этот товар?"},"slides":[{"kind":"learn","title":{"uz":"Talab nima","ru":"Что такое спрос"},"body":{"uz":"Talab – odamlar mahsulotni qidiryapti va sotib olyapti degani. Talabsiz eng yaxshi mahsulot ham sotilmaydi.","ru":"Спрос – это когда люди ищут и покупают товар. Без спроса не продастся даже лучший товар."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Qidiruvda taklif qilinadigan so''zlar","ru":"Подсказки в поиске Amazon"},{"uz":"Raqobatchilar soni va sharhlari","ru":"Число конкурентов и их отзывы"},{"uz":"Best Sellers Rank (BSR)","ru":"Best Sellers Rank (BSR)"},{"uz":"Narxlar oralig''i","ru":"Диапазон цен"}]}},{"kind":"learn","title":{"uz":"BSR nima","ru":"Что такое BSR"},"body":{"uz":"BSR – mahsulotning o''z toifasidagi sotuv o''rni. Raqam qanchalik kichik bo''lsa, mahsulot shunchalik yaxshi sotiladi. Bu taxminiy ko''rsatkich, uni bir necha kun kuzating.","ru":"BSR – место товара по продажам в своей категории. Чем меньше число, тем лучше продаётся товар. Это ориентир: наблюдайте его несколько дней."},"visual":{"kind":"big","icon":"chart","text":{"uz":"Kichik BSR = ko''p sotuv","ru":"Маленький BSR = много продаж"}}},{"kind":"learn","title":{"uz":"Yaxshi va yomon belgi","ru":"Хороший и плохой знак"},"body":{"uz":"Talab bo''lishi kerak, lekin bozor faqat yirik sotuvchilar qo''lida bo''lmasin.","ru":"Спрос должен быть, но рынок не должен принадлежать только крупным продавцам."},"visual":{"kind":"compare","left":{"title":{"uz":"Yaxshi","ru":"Хорошо"},"items":[{"uz":"Talab barqaror","ru":"Спрос стабильный"},{"uz":"Sharhi kam sotuvchilar ham sotyapti","ru":"Продают и продавцы с малым числом отзывов"}]},"right":{"title":{"uz":"Yomon","ru":"Плохо"},"items":[{"uz":"Birinchi sahifada hammada minglab sharh","ru":"На первой странице у всех тысячи отзывов"},{"uz":"Faqat mavsumiy talab","ru":"Спрос только сезонный"}]}}},{"kind":"learn","title":{"uz":"Taxmin emas, dalil","ru":"Не догадки, а факты"},"body":{"uz":"Raqamlarni o''ylab topmang. Har bir xulosa uchun manbani yozib qo''ying: qaysi sahifa va qaysi sana.","ru":"Не придумывайте цифры. Для каждого вывода записывайте источник: какая страница и какая дата."}},{"kind":"quiz","question":{"uz":"BSR kichik bo''lsa, bu nimani anglatadi?","ru":"Что значит маленький BSR?"},"options":[{"uz":"Kam sotiladi","ru":"Продаётся мало"},{"uz":"Yaxshi sotiladi","ru":"Продаётся хорошо"},{"uz":"Narxi past","ru":"Цена низкая"}],"correct":1,"explain":{"uz":"BSR – sotuv reytingi: 1-o''rin eng ko''p sotilayotgan mahsulot.","ru":"BSR – рейтинг продаж: 1-е место у самого продаваемого товара."}}]}'::jsonb),
  ('find-supplier', 0, 4, true, '{"minutes":5,"icon":"globe","title":{"uz":"Yetkazib beruvchini topish","ru":"Поиск поставщика"},"summary":{"uz":"Ishonchli zavodni qanday tanlash.","ru":"Как выбрать надёжную фабрику."},"slides":[{"kind":"learn","title":{"uz":"Qayerdan izlash","ru":"Где искать"},"body":{"uz":"Ko''p sotuvchilar Xitoydagi ishlab chiqaruvchilarni Alibaba kabi platformalar orqali topadi. Bitta emas, bir nechta taklif oling.","ru":"Многие продавцы находят производителей в Китае через площадки вроде Alibaba. Берите не одно, а несколько предложений."},"visual":{"kind":"flow","steps":[{"uz":"Qidirish","ru":"Поиск"},{"uz":"3–5 ta taklif","ru":"3–5 предложений"},{"uz":"Solishtirish","ru":"Сравнение"},{"uz":"Namuna","ru":"Образец"}]}},{"kind":"learn","title":{"uz":"Yaxshi belgilar","ru":"Хорошие признаки"},"body":{"uz":"Bu belgilar kafolat emas, lekin xavfni kamaytiradi.","ru":"Это не гарантия, но риск меньше."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Platformada tasdiqlangan sotuvchi","ru":"Проверенный продавец на площадке"},{"uz":"Bir necha yillik tajriba","ru":"Несколько лет работы"},{"uz":"Savollarga tez va aniq javob","ru":"Быстрые и чёткие ответы"},{"uz":"Namuna yuborishga tayyor","ru":"Готов отправить образец"}]}},{"kind":"learn","title":{"uz":"Xavfli belgilar","ru":"Тревожные признаки"},"body":{"uz":"Bulardan birini ko''rsangiz, to''xtang va ota-onangiz bilan maslahatlashing.","ru":"Увидели одно из этого – остановитесь и посоветуйтесь с родителями."},"visual":{"kind":"checklist","tone":"bad","items":[{"uz":"Narx boshqalardan juda past","ru":"Цена намного ниже, чем у всех"},{"uz":"To''lovni shaxsiy kartaga so''raydi","ru":"Просит оплату на личную карту"},{"uz":"Savollarga noaniq javob","ru":"Уклончивые ответы"},{"uz":"Platformadan tashqarida to''lashga undaydi","ru":"Уговаривает платить вне площадки"}]}},{"kind":"quiz","question":{"uz":"Qaysi biri xavfli belgi?","ru":"Что из этого – тревожный признак?"},"options":[{"uz":"Namuna yuborishga tayyor","ru":"Готов отправить образец"},{"uz":"To''lovni shaxsiy kartaga so''raydi","ru":"Просит оплату на личную карту"},{"uz":"5 yillik tajriba","ru":"5 лет работы"}],"correct":1,"explain":{"uz":"Platformadan tashqari shaxsiy to''lovda pulingiz himoyalanmaydi.","ru":"При оплате на личную карту вне площадки ваши деньги не защищены."}}]}'::jsonb),
  ('supplier-quote', 0, 5, true, '{"minutes":6,"icon":"clipboard","title":{"uz":"Yetkazib beruvchi taklifini o''qish","ru":"Как читать предложение поставщика"},"summary":{"uz":"MOQ, dona narxi, muddat va EXW/FOB.","ru":"MOQ, цена за штуку, сроки и EXW/FOB."},"slides":[{"kind":"learn","title":{"uz":"Asosiy atamalar","ru":"Главные термины"},"body":{"uz":"Har bir taklifda shu to''rtta narsani toping.","ru":"В каждом предложении найдите эти четыре пункта."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"MOQ – eng kam buyurtma miqdori","ru":"MOQ – минимальный объём заказа"},{"uz":"Dona narxi (miqdorga qarab o''zgaradi)","ru":"Цена за штуку (зависит от объёма)"},{"uz":"Ishlab chiqarish muddati","ru":"Срок производства"},{"uz":"Yetkazish sharti (EXW, FOB)","ru":"Условия поставки (EXW, FOB)"}]}},{"kind":"learn","title":{"uz":"EXW va FOB","ru":"EXW и FOB"},"body":{"uz":"Bu atamalar narxga nimalar kirishini bildiradi. Bir xil narx turli shartda turlicha qimmat bo''lishi mumkin.","ru":"Эти термины показывают, что входит в цену. Одинаковая цена на разных условиях может стоить по-разному."},"visual":{"kind":"compare","left":{"title":{"uz":"EXW","ru":"EXW"},"items":[{"uz":"Narx zavod eshigida","ru":"Цена у ворот фабрики"},{"uz":"Yuklash va yetkazish sizdan","ru":"Погрузка и доставка на вас"}]},"right":{"title":{"uz":"FOB","ru":"FOB"},"items":[{"uz":"Zavod portda kemaga yuklab beradi","ru":"Фабрика грузит товар на судно в порту"},{"uz":"Keyingi yo''l sizdan","ru":"Дальнейший путь на вас"}]}}},{"kind":"learn","title":{"uz":"Misol hisob","ru":"Пример расчёта"},"body":{"uz":"Bu o''quv misoli. Haqiqiy raqamlar sizning taklifingizda bo''ladi.","ru":"Это учебный пример. Реальные цифры будут в вашем предложении."},"visual":{"kind":"formula","caption":{"uz":"Misol","ru":"Пример"},"lines":[{"label":{"uz":"Miqdor","ru":"Количество"},"value":"300"},{"op":"×","label":{"uz":"Dona narxi","ru":"Цена за штуку"},"value":"$1.20"},{"op":"=","label":{"uz":"Tovar uchun","ru":"За товар"},"value":"$360"}]}},{"kind":"quiz","question":{"uz":"MOQ nima?","ru":"Что такое MOQ?"},"options":[{"uz":"Eng kam buyurtma miqdori","ru":"Минимальный объём заказа"},{"uz":"Yetkazish muddati","ru":"Срок доставки"},{"uz":"Bojxona to''lovi","ru":"Таможенный платёж"}],"correct":0,"explain":{"uz":"MOQ – zavod qabul qiladigan eng kichik buyurtma.","ru":"MOQ – самый маленький заказ, который примет фабрика."}}]}'::jsonb),
  ('profit-math', 0, 6, true, '{"minutes":6,"icon":"calc","title":{"uz":"Foydani to''g''ri hisoblash","ru":"Как правильно считать прибыль"},"summary":{"uz":"Foyda, marja, ROI va zararsizlik narxi.","ru":"Прибыль, маржа, ROI и точка безубыточности."},"slides":[{"kind":"learn","title":{"uz":"Dona uchun foyda","ru":"Прибыль с одной штуки"},"body":{"uz":"Barcha xarajatlarni ayiring. Bitta xarajatni unutsangiz, foyda aslida zararga aylanishi mumkin.","ru":"Вычтите все расходы. Забыли один – и «прибыль» может оказаться убытком."},"visual":{"kind":"formula","caption":{"uz":"Misol","ru":"Пример"},"lines":[{"label":{"uz":"Sotuv narxi","ru":"Цена продажи"},"value":"$12.99"},{"op":"−","label":{"uz":"Komissiya (15%)","ru":"Комиссия (15%)"},"value":"$1.95"},{"op":"−","label":{"uz":"FBA to''lovi","ru":"Плата FBA"},"value":"$3.50"},{"op":"−","label":{"uz":"Tovar","ru":"Товар"},"value":"$1.80"},{"op":"−","label":{"uz":"Yetkazish","ru":"Доставка"},"value":"$1.10"},{"op":"=","label":{"uz":"Foyda","ru":"Прибыль"},"value":"$4.64"}]}},{"kind":"learn","title":{"uz":"Marja va ROI","ru":"Маржа и ROI"},"body":{"uz":"Marja – sotuv narxining qancha qismi foyda. ROI – sarflagan pulingizga nisbatan qancha foyda.","ru":"Маржа – какая часть цены продажи остаётся прибылью. ROI – сколько прибыли на вложенные деньги."},"visual":{"kind":"formula","lines":[{"label":{"uz":"Marja = Foyda ÷ Sotuv narxi","ru":"Маржа = Прибыль ÷ Цена продажи"}},{"label":{"uz":"ROI = Foyda ÷ Sarflangan pul","ru":"ROI = Прибыль ÷ Вложения"}}]}},{"kind":"learn","title":{"uz":"Zararsizlik narxi","ru":"Точка безубыточности"},"body":{"uz":"Bu – foyda nolga teng bo''ladigan narx. Undan arzon sotsangiz, zarar ko''rasiz.","ru":"Это цена, при которой прибыль равна нулю. Продаёте дешевле – уходите в минус."},"visual":{"kind":"big","icon":"calc","text":{"uz":"Idrok buni Mahsulotlar bo''limida avtomatik hisoblaydi","ru":"Idrok считает это автоматически в разделе «Товары»"}}},{"kind":"quiz","question":{"uz":"Foyda 4 $, sotuv narxi 20 $. Marja qancha?","ru":"Прибыль 4 $, цена продажи 20 $. Какая маржа?"},"options":[{"uz":"4%","ru":"4%"},{"uz":"20%","ru":"20%"},{"uz":"80%","ru":"80%"}],"correct":1,"explain":{"uz":"4 ÷ 20 = 0,2, ya''ni 20%.","ru":"4 ÷ 20 = 0,2, то есть 20%."}}]}'::jsonb),
  ('fees', 0, 7, true, '{"minutes":5,"icon":"clipboard","title":{"uz":"Komissiya va to''lovlar","ru":"Комиссии и сборы"},"summary":{"uz":"Marketpleys sizdan nimalar uchun pul oladi.","ru":"За что маркетплейс берёт деньги."},"slides":[{"kind":"learn","title":{"uz":"Amazon to''lovlari","ru":"Сборы Amazon"},"body":{"uz":"Asosiy to''lovlar shular. Aniq stavkalar toifa va o''lchamga bog''liq va vaqt o''tishi bilan o''zgaradi, shuning uchun rasmiy narxlar sahifasini tekshiring.","ru":"Основные сборы такие. Точные ставки зависят от категории и размера и со временем меняются, поэтому проверяйте официальную страницу цен."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Savdo komissiyasi: ko''p toifalarda narxning taxminan 15%","ru":"Комиссия с продажи: во многих категориях около 15% цены"},{"uz":"FBA to''lovi: har bir dona uchun","ru":"Плата FBA: за каждую штуку"},{"uz":"Ombor to''lovi: oyiga, hajmga qarab","ru":"Хранение: в месяц, по объёму"},{"uz":"Sotuvchi rejasi uchun oylik to''lov","ru":"Ежемесячная плата за план продавца"}]}},{"kind":"learn","title":{"uz":"Nega kichik va yengil?","ru":"Почему маленький и лёгкий?"},"body":{"uz":"FBA to''lovi mahsulot o''lchami va og''irligiga bog''liq. Kichik va yengil tovar arzonroq saqlanadi va jo''natiladi.","ru":"Плата FBA зависит от размера и веса. Маленький и лёгкий товар дешевле хранить и отправлять."},"visual":{"kind":"big","icon":"box","text":{"uz":"Kichikroq = arzonroq to''lov","ru":"Меньше = дешевле сборы"}}},{"kind":"learn","title":{"uz":"Uzum Market","ru":"Uzum Market"},"body":{"uz":"Uzum''da komissiya toifaga qarab farq qiladi, logistika uchun ham alohida to''lov bo''lishi mumkin. Joriy stavkalarni Uzum sotuvchilar kabinetida tekshiring.","ru":"На Uzum комиссия зависит от категории, может быть и отдельная плата за логистику. Актуальные ставки смотрите в кабинете продавца Uzum."}},{"kind":"quiz","question":{"uz":"FBA to''loviga nima eng ko''p ta''sir qiladi?","ru":"Что сильнее всего влияет на плату FBA?"},"options":[{"uz":"Mahsulot rangi","ru":"Цвет товара"},{"uz":"O''lcham va og''irlik","ru":"Размер и вес"},{"uz":"Sotuvchining yoshi","ru":"Возраст продавца"}],"correct":1,"explain":{"uz":"FBA to''lovi o''lcham va og''irlik toifasiga qarab belgilanadi.","ru":"Плата FBA определяется по размеру и весу."}}]}'::jsonb),
  ('shipping', 0, 8, true, '{"minutes":5,"icon":"truck","title":{"uz":"Yetkazish va bojxona","ru":"Доставка и таможня"},"summary":{"uz":"Havo yoki dengiz, ekspeditor va boj.","ru":"Авиа или море, экспедитор и пошлина."},"slides":[{"kind":"learn","title":{"uz":"Havo yoki dengiz","ru":"Самолёт или море"},"body":{"uz":"Muddatlar yo''nalish va mavsumga qarab o''zgaradi. Quyidagilar umumiy yo''nalish.","ru":"Сроки зависят от маршрута и сезона. Ниже – общая картина."},"visual":{"kind":"compare","left":{"title":{"uz":"Havo","ru":"Авиа"},"items":[{"uz":"Tezroq","ru":"Быстрее"},{"uz":"Qimmatroq","ru":"Дороже"},{"uz":"Kichik partiya uchun","ru":"Для малых партий"}]},"right":{"title":{"uz":"Dengiz","ru":"Море"},"items":[{"uz":"Sekinroq, bir necha hafta","ru":"Медленнее, несколько недель"},{"uz":"Arzonroq","ru":"Дешевле"},{"uz":"Katta partiya uchun","ru":"Для больших партий"}]}}},{"kind":"learn","title":{"uz":"Ekspeditor","ru":"Экспедитор"},"body":{"uz":"Ekspeditor (freight forwarder) tovarni zavoddan Amazon omborigacha olib boradi va hujjatlarni rasmiylashtirishga yordam beradi.","ru":"Экспедитор (freight forwarder) везёт товар от фабрики до склада Amazon и помогает с документами."},"visual":{"kind":"flow","steps":[{"uz":"Zavod","ru":"Фабрика"},{"uz":"Ekspeditor","ru":"Экспедитор"},{"uz":"Bojxona","ru":"Таможня"},{"uz":"Amazon ombori","ru":"Склад Amazon"}]}},{"kind":"learn","title":{"uz":"Bojxona boji","ru":"Таможенная пошлина"},"body":{"uz":"AQShga olib kirilganda tovar turiga qarab boj to''lanishi mumkin. Tovar kodi (HTS) aniqlanadi. Bojni foyda hisobidagi \"yetkazish va bojxona\" qatoriga qo''shing.","ru":"При ввозе в США в зависимости от товара может взиматься пошлина. Определяется код товара (HTS). Добавьте пошлину в строку «доставка и таможня» в расчёте прибыли."}},{"kind":"quiz","question":{"uz":"Kichik birinchi partiya uchun odatda qaysi usul qulayroq?","ru":"Какой способ обычно удобнее для небольшой первой партии?"},"options":[{"uz":"Havo","ru":"Авиа"},{"uz":"Dengiz","ru":"Море"},{"uz":"Farqi yo''q","ru":"Без разницы"}],"correct":0,"explain":{"uz":"Kichik partiyada havo tezroq va hajm kam bo''lgani uchun farq unchalik katta emas.","ru":"Для малой партии авиа быстрее, а из-за малого объёма разница в цене не так велика."}}]}'::jsonb),
  ('samples', 0, 9, true, '{"minutes":4,"icon":"check","title":{"uz":"Namuna va sifat","ru":"Образец и качество"},"summary":{"uz":"Katta buyurtmadan oldin tekshiring.","ru":"Проверяйте до большого заказа."},"slides":[{"kind":"learn","title":{"uz":"Avval namuna","ru":"Сначала образец"},"body":{"uz":"Katta buyurtmadan oldin namuna buyurtma qiling va tovarni qo''lingizda ushlab ko''ring. Bu eng arzon sug''urta.","ru":"Перед большим заказом закажите образец и подержите товар в руках. Это самая дешёвая страховка."},"visual":{"kind":"flow","steps":[{"uz":"Namuna","ru":"Образец"},{"uz":"Tekshiruv","ru":"Проверка"},{"uz":"Tasdiqlash","ru":"Одобрение"},{"uz":"Buyurtma","ru":"Заказ"}]}},{"kind":"learn","title":{"uz":"Nimani tekshirish","ru":"Что проверять"},"body":{"uz":"Namunani taklifdagi ma''lumotlar bilan solishtiring.","ru":"Сравните образец с тем, что указано в предложении."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"O''lcham va og''irlik","ru":"Размер и вес"},{"uz":"Material sifati","ru":"Качество материала"},{"uz":"Qadoq","ru":"Упаковка"},{"uz":"Hid, chiqib turgan joylar, ishlov","ru":"Запах, заусенцы, обработка"}]}},{"kind":"learn","title":{"uz":"Jo''natishdan oldin tekshiruv","ru":"Проверка перед отправкой"},"body":{"uz":"Ommaviy ishlab chiqarishdan keyin ham tovarni jo''natishdan oldin tekshirtirish mumkin. Bu nuqsonli partiyadan himoya qiladi.","ru":"После массового производства товар можно проверить ещё раз перед отправкой. Это защищает от бракованной партии."}},{"kind":"quiz","question":{"uz":"Katta buyurtmadan oldin nima qilish kerak?","ru":"Что нужно сделать перед большим заказом?"},"options":[{"uz":"Namuna olib tekshirish","ru":"Заказать и проверить образец"},{"uz":"Darhol to''liq to''lash","ru":"Сразу оплатить полностью"},{"uz":"Reklamani boshlash","ru":"Запустить рекламу"}],"correct":0,"explain":{"uz":"Namuna sifat muammosini arzon narxda oldindan ko''rsatadi.","ru":"Образец заранее и недорого показывает проблемы с качеством."}}]}'::jsonb),
  ('listing', 0, 10, true, '{"minutes":5,"icon":"sparkle","title":{"uz":"Yaxshi listing","ru":"Хорошая карточка товара"},"summary":{"uz":"Nom, rasmlar va tavsif.","ru":"Название, фото и описание."},"slides":[{"kind":"learn","title":{"uz":"Nom","ru":"Название"},"body":{"uz":"Nomda odamlar qidiradigan asosiy so''z va eng muhim xususiyat bo''lsin. Ortiqcha so''z va katta harflar bilan to''ldirmang.","ru":"В названии – главное слово, которое ищут люди, и важнейшая характеристика. Без лишних слов и сплошных заглавных."}},{"kind":"learn","title":{"uz":"Rasmlar","ru":"Фотографии"},"body":{"uz":"Amazon''da asosiy rasm toza oq fonda bo''lishi kerak. Qolgan rasmlarda o''lcham, foydalanish va afzalliklarni ko''rsating.","ru":"На Amazon главное фото должно быть на чисто белом фоне. На остальных покажите размер, использование и преимущества."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Asosiy rasm: oq fon","ru":"Главное фото: белый фон"},{"uz":"O''lcham ko''rsatilgan rasm","ru":"Фото с размерами"},{"uz":"Foydalanishdagi rasm","ru":"Фото в использовании"}]}},{"kind":"learn","title":{"uz":"Tavsif","ru":"Описание"},"body":{"uz":"Qisqa punktlarda xaridorga nima foyda berishini yozing. Faqat haqiqatni yozing: soxta va''dalar qaytarish va yomon sharhlarga olib keladi.","ru":"Короткими пунктами напишите, чем товар полезен покупателю. Только правду: ложные обещания ведут к возвратам и плохим отзывам."}},{"kind":"quiz","question":{"uz":"Amazon''da asosiy rasm qanday fonda bo''lishi kerak?","ru":"Какой фон должен быть у главного фото на Amazon?"},"options":[{"uz":"Rangli","ru":"Цветной"},{"uz":"Toza oq","ru":"Чисто белый"},{"uz":"Qora","ru":"Чёрный"}],"correct":1,"explain":{"uz":"Bu Amazon talabi: asosiy rasm toza oq fonda.","ru":"Это требование Amazon: главное фото на чисто белом фоне."}}]}'::jsonb),
  ('risks', 0, 11, true, '{"minutes":5,"icon":"shield","title":{"uz":"Xavflar va ulardan himoya","ru":"Риски и защита от них"},"summary":{"uz":"Brend, sertifikat va qaytarishlar.","ru":"Бренды, сертификаты и возвраты."},"slides":[{"kind":"learn","title":{"uz":"Birovning brendi","ru":"Чужой бренд"},"body":{"uz":"Boshqa birovning logotipi, nomi yoki patentlangan dizaynini nusxalamang. Bu tovarning o''chirilishiga va hisob bloklanishiga olib keladi.","ru":"Не копируйте чужие логотипы, названия и запатентованный дизайн. Это ведёт к удалению товара и блокировке аккаунта."}},{"kind":"learn","title":{"uz":"Sertifikatlar","ru":"Сертификаты"},"body":{"uz":"Ba''zi toifalar, masalan bolalar uchun tovarlar, maxsus sinov va hujjatlarni talab qiladi. 0-darajada bunday toifalardan qoching.","ru":"Некоторые категории, например детские товары, требуют специальных испытаний и документов. На уровне 0 их лучше избегать."},"visual":{"kind":"big","icon":"shield","text":{"uz":"Shubha bo''lsa, tanlamang","ru":"Сомневаетесь – не берите"}}},{"kind":"learn","title":{"uz":"Qaytarishlar","ru":"Возвраты"},"body":{"uz":"Har qanday biznesda qaytarishlar bo''ladi. Eng yaxshi himoya – yaxshi sifat va halol tavsif. Qaytarish xarajatini ham foyda hisobiga kiriting.","ru":"Возвраты бывают в любом бизнесе. Лучшая защита – хорошее качество и честное описание. Учитывайте расходы на возвраты в расчёте прибыли."}},{"kind":"learn","title":{"uz":"Idrok qoidasi","ru":"Правило Idrok"},"body":{"uz":"Xavf agenti istalgan darajada har qanday mahsulot haqida ogohlantirishi mumkin. Xavfliroq mahsulotlar hech qachon mukofot emas.","ru":"Агент рисков может предупредить о любом товаре на любом уровне. Рискованные товары – никогда не награда."}},{"kind":"quiz","question":{"uz":"Qaysi biri xavfsizroq?","ru":"Что безопаснее?"},"options":[{"uz":"Mashhur multfilm qahramoni tasvirli krujka","ru":"Кружка с известным мультгероем"},{"uz":"O''z dizayningizdagi oddiy krujka","ru":"Простая кружка вашего дизайна"},{"uz":"Boshqa brend logotipli krujka","ru":"Кружка с чужим логотипом"}],"correct":1,"explain":{"uz":"Personaj va logotiplar boshqalarning mulki. O''z dizayningiz xavfsiz.","ru":"Персонажи и логотипы – чужая собственность. Свой дизайн безопасен."}}]}'::jsonb)
